// "We need an API for todos. Don't overthink it."
// One handler, one if/else ladder, everything inline.
import http from "node:http";

var todos = [];
var nextId = 1;

var server = http.createServer(function (req, res) {
  // Problem 1: routing is string-surgery repeated per route. Path
  // params mean split("/")[2] and hope. Add a route and you're
  // re-reading the whole ladder to find where it fits.
  if (req.method === "GET" && req.url === "/todos") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify(todos));
  } else if (req.method === "POST" && req.url === "/todos") {
    // Problem 2: body parsing, hand-rolled HERE (and re-rolled in
    // every other POST/PUT below, each copy slightly different).
    var chunks = [];
    req.on("data", function (c) { chunks.push(c); });
    req.on("end", function () {
      // Problem 3: JSON.parse with no try/catch — send `{oops` and
      // the whole PROCESS crashes. One bad client kills the server
      // for everyone.
      var body = JSON.parse(Buffer.concat(chunks).toString());

      // Problem 4: no validation. {"title": ""} or {} or
      // {"title": 12345} all sail in and live in the data forever.
      todos.push({ id: nextId++, title: body.title, done: false });
      res.writeHead(201, { "Content-Type": "application/json" });
      res.end(JSON.stringify(todos[todos.length - 1]));
    });
  } else if (req.method === "PUT" && req.url.startsWith("/todos/")) {
    var id = parseInt(req.url.split("/")[2]); // "abc" -> NaN, no check
    var chunks2 = [];
    req.on("data", function (c) { chunks2.push(c); });
    req.on("end", function () {
      var body = JSON.parse(Buffer.concat(chunks2).toString()); // crash #2
      var found = null;
      for (var i = 0; i < todos.length; i++) {
        if (todos[i].id === id) found = todos[i];
      }
      // Problem 5: error responses are improvised per site — this
      // one is text/plain "nope", others are JSON, the POST above
      // never even checked. Clients can't rely on ANY error shape.
      if (!found) {
        res.writeHead(404);
        res.end("nope");
        return;
      }
      found.done = !!body.done;
      if (body.title) found.title = body.title;
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(JSON.stringify(found));
    });
  } else {
    res.writeHead(404);
    res.end("not found");
  }
  // Problem 6: business rules (what makes a valid todo? what does
  // toggling mean?) are smeared through HTTP plumbing. You cannot
  // test "todos" without booting a server and speaking HTTP.
});

server.listen(3000, function () {
  console.log("listening on http://localhost:3000 — try:");
  console.log('  curl localhost:3000/todos');
  console.log('  curl -X POST localhost:3000/todos -d \'{"title":"try {oops next"}\'');
});

# 🏋️ Practice: REST API (a micro-Express from scratch)

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. Clear the list — one feature, three layers (warm-up)

Add `DELETE /todos` (no id — the whole collection) by touching all three layers in `todos.js`: a `clear()` on the repo, a `removeAll()` on the service, and a one-liner route. Check with the server running: `curl -X DELETE localhost:3000/todos` answers 204, and `curl localhost:3000/todos` then returns `[]`. Note that the route table happily holds both `DELETE /todos` and `DELETE /todos/:id` — the matcher separates them by segment count.

What it practices: walking a new feature through repo → service → route, each layer staying ignorant of the ones above.

Hint: the repo's rows live in a `Map` — `Map` has a built-in `.clear()`.

### ⭐⭐ 2. Filter with a query parameter (core)

Support `GET /todos?done=true` and `?done=false`. The *rule* belongs in the service: extend `list` to take `{ done }`, where `done` must be `undefined`, `'true'`, or `'false'` — anything else throws `HttpError(400, 'done must be "true" or "false"')`. The route passes `ctx.query.get('done') ?? undefined` (careful: `URLSearchParams.get` returns `null` for a missing key). Check: with one open and one done todo, `?done=true` returns only the done one, no query returns both, and `?done=maybe` returns status 400 with the exact `{ error }` shape.

What it practices: query-string input is input too — validate it in the service, not in the route.

Hint: after validating, `all.filter((t) => t.done === (done === 'true'))`.

### ⭐⭐ 3. A requireJson middleware (core)

Write a middleware `requireJson()` that rejects any POST or PUT whose `Content-Type` header doesn't contain `application/json`, by throwing `HttpError(415, 'Content-Type must be application/json')` — before `jsonBody()` ever reads the stream. Register it with `app.use(requireJson())` *above* `app.use(jsonBody())` in `buildApp`. Check: a POST with `Content-Type: text/plain` (or none) gets a 415 JSON error, a normal JSON POST still gets 201, and GETs are untouched.

What it practices: writing a new onion layer — shared policy declared once, and middleware order mattering.

Hint: same shape as `jsonBody`: `(ctx, next) => { ...checks...; return next(ctx); }`; the header is `ctx.req.headers['content-type']`.

### ⭐⭐ 4. Pin two uncovered edges with tests (core)

`api.test.js` never asks these two questions — add them as new tests. First: a `PUT /todos/:id` with body `{}` on an existing todo (no `title`, no `done`) must answer 200 and return the todo *unchanged* — the service builds an empty `fields` object and the repo's spread-merge changes nothing. Second: a title of *exactly* 200 characters must be accepted with 201 (the existing test only proves 201 characters is rejected — boundaries deserve their own test).

What it practices: reading validation code closely enough to spot the untested boundary, then pinning it.

Hint: fetch the todo before the empty PUT and `assert.deepEqual` it against the PUT's response body.

### ⭐⭐⭐ 5. 405 Method Not Allowed (challenge)

Real frameworks distinguish "no such path" (404) from "right path, wrong verb" (405). In `app.js`, the no-match branch currently always throws 404 — change it: if any route of a *different* method matches `ctx.path`, respond 405 with an `Allow` header listing those methods (e.g. `Allow: PUT, DELETE`), else keep the 404. Check: `POST /todos/1` → 405 with `Allow: PUT, DELETE`; `PUT /todos` → 405 with `Allow: GET, POST`; `GET /no/such/route` → still a plain 404 with no `Allow` header; normal requests unaffected.

What it practices: extending the framework itself — the route table is data, so "which methods work here?" is just another query over it.

Hint: `matchRoute([r], ctx.path)` tests a single route against the path; set the header with `ctx.res.setHeader('Allow', ...)` before throwing — `writeHead` in `ctx.json` merges headers set earlier.

## Solutions

### 1. Clear the list

```js
// repo — knows storage, no rules:
clear: () => rows.clear(),

// service — the "rule" here is just delegation:
removeAll() { repo.clear(); },

// routes:
app.delete('/todos', (ctx) => { service.removeAll(); ctx.json(204, null); });
```

WHY: Each layer gains one small, honest method: the repo touches its `Map`, the service exposes the operation without knowing HTTP, and the route translates. `matchRoute` compares segment counts before anything else, so `/todos` (one segment) can never be swallowed by `/todos/:id` (two) — the table stays unambiguous as it grows, which is exactly what the original's if/else ladder couldn't promise.

### 2. `?done=` filter

```js
// service:
list({ done } = {}) {
  if (done !== undefined && done !== 'true' && done !== 'false') {
    throw new HttpError(400, 'done must be "true" or "false"');
  }
  const all = repo.all();
  return done === undefined ? all : all.filter((t) => t.done === (done === 'true'));
},

// route:
app.get('/todos', (ctx) =>
  ctx.json(200, service.list({ done: ctx.query.get('done') ?? undefined })));
```

WHY: Query strings are user input arriving as *strings* — `'true'` is not `true` — so the service states exactly what it accepts and rejects the rest through the same `HttpError` path as body validation, keeping every error in the one `{ error }` shape. The `?? undefined` in the route is pure translation: converting `URLSearchParams`' `null`-for-missing into the service's `undefined`-for-absent vocabulary.

### 3. requireJson middleware

```js
export function requireJson() {
  return (ctx, next) => {
    if (ctx.method === 'POST' || ctx.method === 'PUT') {
      const type = ctx.req.headers['content-type'] ?? '';
      if (!type.includes('application/json')) {
        throw new HttpError(415, 'Content-Type must be application/json');
      }
    }
    return next(ctx);
  };
}

// in buildApp — order matters:
app.use(requireJson());
app.use(jsonBody());
```

WHY: This is the onion earning its keep: a cross-cutting policy written once, applied to every route, and *ordered* — by sitting outside `jsonBody`, it rejects mislabeled requests before any body bytes are read. Throwing `HttpError` means the error boundary formats the 415 exactly like every other failure; the middleware never touches `res` itself.

### 4. The two edge tests

```js
test('PUT with an empty body is a valid no-op update', async () => {
  const { id } = await (await post('/todos', { title: 'unchanged' })).json();
  const before = (await (await fetch(`${base}/todos`)).json()).find((t) => t.id === id);
  const res = await put(`/todos/${id}`, {});
  assert.equal(res.status, 200);
  assert.deepEqual(await res.json(), before);
});

test('a title of exactly 200 chars sits inside the boundary', async () => {
  const res = await post('/todos', { title: 'x'.repeat(200) });
  assert.equal(res.status, 201);
  assert.equal((await res.json()).title.length, 200);
});
```

WHY: `update` only adds fields the client actually sent, so `{}` legitimately means "change nothing" — a test makes that a promise instead of an accident. And validation bugs live at boundaries: the suite proved 201 fails but never that 200 succeeds, so an off-by-one edit (`>=` for `>`) would have passed every existing test while rejecting legal input.

### 5. 405 Method Not Allowed

```js
// in app.js, replacing the 404-only branch:
const endpoint = match
  ? match.route.handler
  : () => {
      const allowed = [...new Set(
        routes.filter((r) => r.method !== ctx.method && matchRoute([r], ctx.path))
              .map((r) => r.method))];
      if (allowed.length > 0) {
        ctx.res.setHeader('Allow', allowed.join(', '));
        throw new HttpError(405, `Method ${ctx.method} not allowed on ${ctx.path}`);
      }
      throw new HttpError(404, `No route: ${ctx.method} ${ctx.path}`);
    };
```

WHY: Because routes are a *table*, "does this path exist under another verb?" is one `filter` over data — in the original's if/else ladder this feature would mean re-reading every branch. The `Allow` header is set on the raw response before the throw; the error boundary's `ctx.json` call uses `writeHead`, which merges previously set headers, so the header survives the normal error path. Both failures still flow through the single boundary: one place decides what 404 and 405 look like on the wire.

// REAL integration tests: the app listens on an OS-assigned port and
// the tests speak actual HTTP with fetch. No mocks — this is the
// payoff of buildApp() being importable instead of listening on load.
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { buildApp } from './server.js';

let server;
let base;

before(async () => {
  server = buildApp().listen(0); // port 0: the OS picks a free one
  await new Promise((r) => server.on('listening', r));
  base = `http://localhost:${server.address().port}`;
});

after(() => server.close());

const post = (path, body) => fetch(base + path, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: typeof body === 'string' ? body : JSON.stringify(body),
});
const put = (path, body) => fetch(base + path, {
  method: 'PUT',
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify(body),
});

test('the CRUD story: create, list, update, delete', async () => {
  const created = await post('/todos', { title: '  write tests  ' });
  assert.equal(created.status, 201);
  const todo = await created.json();
  assert.deepEqual(todo, { id: todo.id, title: 'write tests', done: false }); // trimmed

  const list = await (await fetch(`${base}/todos`)).json();
  assert.ok(list.some((t) => t.id === todo.id));

  const updated = await put(`/todos/${todo.id}`, { done: true });
  assert.equal((await updated.json()).done, true);

  const del = await fetch(`${base}/todos/${todo.id}`, { method: 'DELETE' });
  assert.equal(del.status, 204);
  const after404 = await put(`/todos/${todo.id}`, { done: false });
  assert.equal(after404.status, 404);
});

test('malformed JSON is a 400 for THAT client — not a process crash', async () => {
  const res = await post('/todos', '{oops');
  assert.equal(res.status, 400);
  assert.deepEqual(await res.json(), { error: 'Body must be valid JSON' });
  // and the server is still alive for everyone else:
  assert.equal((await fetch(`${base}/todos`)).status, 200);
});

test('validation: bad bodies are rejected with reasons', async () => {
  for (const [body, why] of [
    [{}, /title/],
    [{ title: '' }, /title/],
    [{ title: '   ' }, /title/],
    [{ title: 12345 }, /title/],
    [{ title: 'x'.repeat(201) }, /too long/],
  ]) {
    const res = await post('/todos', body);
    assert.equal(res.status, 400);
    assert.match((await res.json()).error, why);
  }
});

test('errors have ONE consistent shape everywhere: { error }', async () => {
  const cases = [
    await fetch(`${base}/no/such/route`),
    await put('/todos/abc', { done: true }),   // bad id -> 400
    await put('/todos/99999', { done: true }), // missing -> 404
    await post('/todos', {}),                  // invalid -> 400
  ];
  for (const res of cases) {
    assert.ok(res.status >= 400);
    const body = await res.json();
    assert.deepEqual(Object.keys(body), ['error']); // never "nope", never HTML
  }
});

test('route params: /todos/:id parses via the same matcher as project 60', async () => {
  const res = await put('/todos/abc', { done: true });
  assert.equal(res.status, 400);
  assert.match((await res.json()).error, /Invalid id: "abc"/);
});

test('unknown update fields are ignored; typed wrong they are 400', async () => {
  const { id } = await (await post('/todos', { title: 'strict' })).json();
  const res = await put(`/todos/${id}`, { done: 'yes' });
  assert.equal(res.status, 400);
  assert.match((await res.json()).error, /done must be a boolean/);
});

/**
 * A micro-Express on node:http, ~80 lines. The three ideas every
 * HTTP framework is made of:
 *
 *   1. A ROUTE TABLE with patterns — reusing project 60's matcher.
 *      The same pure matchRoute that drove a browser SPA drives a
 *      server; URLs don't care which side they're parsed on.
 *   2. A MIDDLEWARE CHAIN — an onion of async (ctx, next) functions.
 *      Body parsing, logging, auth: each written once, composed.
 *   3. ONE error boundary — handlers THROW (HttpError for intentional
 *      statuses); a single place converts failures to consistent
 *      JSON. No per-route improvised error responses.
 */
import http from 'node:http';
import { matchRoute } from '../../60-router/refactored/router.js';

export class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.name = 'HttpError';
    this.status = status;
  }
}

export function createApp() {
  const middlewares = [];
  const routes = []; // { method, path, handler } — a table, not a ladder

  const app = {
    use: (fn) => middlewares.push(fn),
    listen: (port, cb) => http.createServer(handle).listen(port, cb),
    handle, // exposed for tests
  };
  for (const method of ['get', 'post', 'put', 'delete']) {
    app[method] = (path, handler) =>
      routes.push({ method: method.toUpperCase(), path, handler });
  }

  async function handle(req, res) {
    const url = new URL(req.url, `http://${req.headers.host ?? 'local'}`);
    const ctx = {
      req, res,
      method: req.method,
      path: url.pathname,
      query: url.searchParams,
      params: {},
      body: undefined,
      // the response helper: EVERY response goes through here,
      // so every response is JSON with a status — consistency by
      // construction.
      json(status, data) {
        res.writeHead(status, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(data));
      },
    };

    // find the route now so middleware can know about it if needed
    const candidates = routes.filter((r) => r.method === ctx.method);
    const match = matchRoute(candidates, ctx.path);
    if (match) ctx.params = match.params;

    const endpoint = match
      ? match.route.handler
      : () => { throw new HttpError(404, `No route: ${ctx.method} ${ctx.path}`); };

    // Build the onion: mw[0] runs first, endpoint is the core.
    const chain = [...middlewares, (c) => endpoint(c)];
    const dispatch = (i) => async (c) =>
      i < chain.length - 1 ? chain[i](c, dispatch(i + 1)) : chain[i](c);

    // THE error boundary — the only try/catch in the framework.
    try {
      await dispatch(0)(ctx);
    } catch (err) {
      if (err instanceof HttpError) {
        ctx.json(err.status, { error: err.message });
      } else {
        console.error(err); // real bugs get logged loudly...
        ctx.json(500, { error: 'Internal server error' }); // ...not leaked
      }
    }
  }

  return app;
}

/**
 * Body-parsing middleware: written once, used by every route.
 * Malformed JSON is a 400 (the client's fault, said clearly) —
 * in the original it was a process crash.
 */
export function jsonBody({ limitBytes = 1_000_000 } = {}) {
  return async (ctx, next) => {
    if (ctx.method === 'POST' || ctx.method === 'PUT') {
      const chunks = [];
      let size = 0;
      for await (const chunk of ctx.req) {
        size += chunk.length;
        if (size > limitBytes) throw new HttpError(413, 'Body too large');
        chunks.push(chunk);
      }
      const text = Buffer.concat(chunks).toString() || '{}';
      try {
        ctx.body = JSON.parse(text);
      } catch {
        throw new HttpError(400, 'Body must be valid JSON');
      }
    }
    return next(ctx);
  };
}

/**
 * Composition root: build the app from its parts and listen.
 * Everything here is a choice a DIFFERENT deployment could make
 * differently (port, middleware, which features to mount).
 *
 *   node 65-rest-api/refactored/server.js
 *   curl localhost:3000/todos
 *   curl -X POST localhost:3000/todos -H 'content-type: application/json' -d '{"title":"hi"}'
 */
import { createApp, jsonBody } from './app.js';
import { createRepo, createService, registerTodoRoutes } from './todos.js';

export function buildApp() {
  const app = createApp();
  app.use(jsonBody());
  registerTodoRoutes(app, createService(createRepo()));
  return app;
}

// Only listen when run directly (tests import buildApp instead).
if (import.meta.url === `file:///${process.argv[1].replace(/\\/g, '/')}`) {
  buildApp().listen(3000, () => console.log('listening on http://localhost:3000'));
}

/**
 * The todos feature in three layers — each testable without the one
 * above it, none knowing about the one above it:
 *
 *   repo     — storage. Knows Maps (or, later, a database). No rules.
 *   service  — business rules. Knows todos. No HTTP.
 *   routes   — translation. Knows HTTP. No rules, no storage.
 *
 * "Where does this code go?" now has an answer, which is most of
 * what 'architecture' means day-to-day.
 */
import { HttpError } from './app.js';

// ---------- repo ------------------------------------------------------
export function createRepo() {
  const rows = new Map();
  let nextId = 1;
  return {
    all: () => [...rows.values()],
    get: (id) => rows.get(id),
    insert(fields) {
      const row = { id: nextId++, ...fields };
      rows.set(row.id, row);
      return row;
    },
    update(id, fields) {
      const row = { ...rows.get(id), ...fields };
      rows.set(id, row);
      return row;
    },
    delete: (id) => rows.delete(id),
  };
}

// ---------- service ---------------------------------------------------
// Rules live here: what a valid title is, what ids mean, what
// "not found" is. Throws HttpError — the boundary translates.
export function createService(repo) {
  function parseId(raw) {
    const id = Number(raw);
    if (!Number.isInteger(id) || id < 1) {
      throw new HttpError(400, `Invalid id: "${raw}"`);
    }
    return id;
  }

  function mustExist(id) {
    const todo = repo.get(id);
    if (!todo) throw new HttpError(404, `No todo with id ${id}`);
    return todo;
  }

  return {
    list: () => repo.all(),

    create({ title } = {}) {
      if (typeof title !== 'string' || title.trim() === '') {
        throw new HttpError(400, 'title must be a non-empty string');
      }
      if (title.length > 200) throw new HttpError(400, 'title too long (max 200)');
      return repo.insert({ title: title.trim(), done: false });
    },

    update(rawId, { title, done } = {}) {
      const id = parseId(rawId);
      mustExist(id);
      const fields = {};
      if (title !== undefined) {
        if (typeof title !== 'string' || title.trim() === '') {
          throw new HttpError(400, 'title must be a non-empty string');
        }
        fields.title = title.trim();
      }
      if (done !== undefined) {
        if (typeof done !== 'boolean') throw new HttpError(400, 'done must be a boolean');
        fields.done = done;
      }
      return repo.update(id, fields);
    },

    remove(rawId) {
      const id = parseId(rawId);
      mustExist(id);
      repo.delete(id);
    },
  };
}

// ---------- routes ----------------------------------------------------
// Pure translation: HTTP in, service call, HTTP out. Thin enough
// that there's nowhere for a bug to hide.
export function registerTodoRoutes(app, service) {
  app.get('/todos', (ctx) => ctx.json(200, service.list()));
  app.post('/todos', (ctx) => ctx.json(201, service.create(ctx.body)));
  app.put('/todos/:id', (ctx) => ctx.json(200, service.update(ctx.params.id, ctx.body)));
  app.delete('/todos/:id', (ctx) => {
    service.remove(ctx.params.id);
    ctx.json(204, null);
  });
}
